<?php include 'db.php'; $msg=''; if($_SERVER['REQUEST_METHOD']=='POST'){ $conn->begin_transaction(); try{ $stmt=$conn->prepare("INSERT INTO USER_ACCOUNT(Username,Password,Role) VALUES(?,?,'Patient')"); $stmt->bind_param('ss',$_POST['username'],$_POST['password']); $stmt->execute(); $uid=$conn->insert_id; $stmt=$conn->prepare("INSERT INTO PATIENT(SSN,First_Name,Last_Name,Gender,Date_of_Birth,Street,City,Medical_History,Admission_Date,User_ID) VALUES(?,?,?,?,?,?,?,?,CURDATE(),?)"); $stmt->bind_param('ssssssssi',$_POST['ssn'],$_POST['first'],$_POST['last'],$_POST['gender'],$_POST['dob'],$_POST['street'],$_POST['city'],$_POST['history'],$uid); $stmt->execute(); $pid=$conn->insert_id; if(!empty($_POST['phone'])){ $stmt=$conn->prepare("INSERT INTO PATIENT_PHONE VALUES(?,?)"); $stmt->bind_param('is',$pid,$_POST['phone']); $stmt->execute(); } $conn->commit(); $msg='Registration completed. You can login now.'; } catch(Exception $e){ $conn->rollback(); $msg='Error: '.$e->getMessage(); }} $page_title='Register'; include 'header.php'; ?>
<h2>Patient Registration</h2><?php if($msg) echo '<div class="alert">'.esc($msg).'</div>'; ?>
<form class="form" method="post"><div class="grid2"><input name="first" placeholder="First Name" required><input name="last" placeholder="Last Name" required></div><div class="grid2"><input name="username" placeholder="Username" required><input name="password" type="password" placeholder="Password" required></div><div class="grid2"><input name="ssn" placeholder="SSN"><input name="phone" placeholder="Phone"></div><div class="grid2"><select name="gender"><option>Male</option><option>Female</option></select><input name="dob" type="date"></div><div class="grid2"><input name="street" placeholder="Street"><input name="city" placeholder="City"></div><textarea name="history" placeholder="Medical History"></textarea><button>Register</button></form>
<?php include 'footer.php'; ?>